import math

def _get_joints(agent_components):
    if isinstance(agent_components, dict):
        return agent_components.get("joints", [])
    return []

def build_agent(sandbox):
    start_x = 10.0
    start_y = 2.5
    # Create a lightweight, compact chassis
    torso = sandbox.add_beam(x=start_x, y=start_y, width=1.0, height=0.2, density=0.5)
    sandbox.set_material_properties(torso, restitution=0.1, friction=0.008)  # Max allowed friction

    # Add two wheels with sufficient clearance and friction
    wheel_radius = 0.25  # Larger radius for better traction and stability
    wheel_density = 0.6
    wheel1 = sandbox.add_wheel(x=start_x - 1.0, y=1.0 + wheel_radius, radius=wheel_radius, density=wheel_density)
    wheel2 = sandbox.add_wheel(x=start_x + 1.0, y=1.0 + wheel_radius, radius=wheel_radius, density=wheel_density)

    # Connect wheels to chassis with wide joint rotation range
    joint1 = sandbox.add_joint(torso, wheel1, (start_x - 1.0, start_y), type='pivot', lower_limit=-math.pi, upper_limit=math.pi)
    joint2 = sandbox.add_joint(torso, wheel2, (start_x + 1.0, start_y), type='pivot', lower_limit=-math.pi, upper_limit=math.pi)

    return {"body": torso, "joints": [joint1, joint2]}

def agent_action(sandbox, agent_body, step_count):
    joints = _get_joints(agent_body)
    torso = agent_body.get("body")
    if torso is not None and torso.position.x < 25.0:
        # Drive wheels forward with moderate speed to avoid slipping
        for j in joints:
            sandbox.set_motor(j, -5.0, max_torque=100.0)
    else:
        # Stop once target is reached
        for j in joints:
            sandbox.set_motor(j, 0.0, max_torque=100.0)
